// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { graphGuide } from "../../../main/frontend/graph-explorer/explorer-help.ts";

/** The guide as the help popover shows it: section titles, then each gesture and what it does, then the notes. */
const guideText = (apple) =>
  graphGuide(apple)
    .flatMap((section) => [
      section.title,
      ...section.items.map((item) => `${item.keys} — ${item.text}`),
      ...(section.notes ?? []),
    ])
    .join("\n");

test("the graph guide names the selection keys, zoom gesture and undo keys of a Mac", () => {
  const guide = guideText(true);
  assert.match(guide, /Shift- or ⌘-click/);
  assert.match(guide, /Pinch — Zoom/);
  assert.match(guide, /⌘Z/);
  assert.doesNotMatch(guide, /Ctrl/);
});

test("elsewhere the guide names Ctrl and zooms with the scroll wheel", () => {
  const guide = guideText(false);
  assert.match(guide, /Shift- or Ctrl-click/);
  assert.match(guide, /Scroll — Zoom/);
  assert.match(guide, /Ctrl\+Z/);
  assert.doesNotMatch(guide, /⌘/);
});

test("the guide shows the gestures and keys the canvas only told screen readers about", () => {
  const guide = guideText(false);
  for (const gesture of [
    /Click a node — Show its details/,
    /Double-click a node — Load its neighbours/,
    /Right-click or long-press a node/,
    /Click a link — /,
    /\+N on a node — /,
    /^\/ — Find a node/m,
    /Arrow keys — /,
    /^Delete — /m,
    /^Escape — /m,
  ])
    assert.match(guide, gesture);
});

test("the guide says that nothing done to the graph changes the repository", () => {
  assert.match(guideText(true), /never change[s]? the repository/);
});
